"""

def __init__(
    self,
    is_checkpoint_mxfp4_serialized: bool = False,
    ignored_layers: list[str] | None = None,
    hadamard_block_size: int = 32,
) -> None:
    super().__init__()
    self.is_checkpoint_mxfp4_serialized = is_checkpoint_mxfp4_serialized
    self.ignored_layers = ignored_layers or []
    # Block-wise Hadamard rotation for the online (BF16 -> FP4) path.
    # <= 1 disables it; 32 matches the MXFP4 group size (see _hadamard.py).
    if hadamard_block_size and (hadamard_block_size & (hadamard_block_size - 1)):
        raise ValueError(
            "hadamard_block_size must be a power of two or <= 1 to disable, "
            f"got {hadamard_block_size}."
        )
    self.hadamard_block_size = hadamard_block_size or 0

