{"file_text": "# SPDX-License-Identifier: Apache-2.0
# SPDX-FileCopyrightText: Copyright contributors to the vLLM project
"""Fused XPU Hadamard + MXFP4 quantization op (AutoRound Kernel / ARK).

This mirrors the XPU path of PR vllm-project/vllm#54006, which quantizes an
activation with a *fused* Hadamard-rotation + MXFP4-quantize XPU kernel:

    x_fp4, x_blockscale = torch.ops.vllm.inc_ark_mxfp4_hadamard_quant(x)

The underlying kernel comes from ``auto_round_kernel.mxfp4_hadamard`` (ARK), the
Intel XPU-optimized kernel library. In this fork we load a **BF16** checkpoint,
so the *weight* is quantized online too — we therefore run the **same** fused op
on both the weight (at load time) and the activation (at runtime), which
guarantees an identical Hadamard rotation on both sides and keeps
``(x·H) @ (W·H)ᵀ == x @ Wᵀ`` (output-preserving) while improving FP4 accuracy.

The raw kernel returns packed ``uint8`` tensors; :func:`mxfp4_hadamard_quantize`
reinterprets them as ``float4_e2m1fn_x2`` / ``float8_e8m0fnu`` so the result is
drop-in compatible with ``xpu_mxfp4_quantize`` (same dtypes/shapes) and thus with
the existing ``XPUMxFp4LinearKernel.process_weights_after_loading`` and
``torch.ops._xpu_C.fp4_gemm`` call sites.
"""

from __future__ import annotations

import torch
from vllm.logger import init_logger
from vllm.platforms import current_platform
from vllm.utils.torch_utils import direct_register_custom_op

logger = init_logger(__name__)

__all__ = ["is_available", "mxfp4_hadamard_quantize"]

_OPS_REGISTERED = False


def _ark_is_available() -> bool:
    """Return True iff the ARK backend library is importable and loaded."""
    try:
        from vllm.model_executor.layers.quantization.inc.schemes.inc_ark_ops import (
            get_ark_state,
        )

        return bool(get_ark_state()[0])
    except Exception as exc:  # pragma: no cover - defensive
        logger.debug("ARK availability check failed: %s", exc)
        return False


def _inc_ark_mxfp4_hadamard_quant_impl(
    x: torch.Tensor,
) -> tuple[torch.Tensor, torch.Tensor]:
    from auto_round_kernel.mxfp4_hadamard import mxfp4_hadamard_quant

    return mxfp4_hadamard_quant(x)


def _inc_ark_mxfp4_hadamard_quant_fake(
    x: torch.Tensor,
) -> tuple[torch.Tensor, torch.Tensor]:
    return (
        torch.empty(
            (*x.shape[:-1], x.shape[-1] // 2), dtype=torch.uint8, device=x.device
        ),
        torch.empty(
            (*x.shape[:-1], x.shape[-1] // 32), dtype=torch.uint8, device=x.device
        ),
    )


def _register_ops_once() -> bool:
    """Register ``vllm::inc_ark_mxfp4_hadamard_quant``; return availability."""
    global _OPS_REGISTERED
    if _OPS_REGISTERED:
        return True
    if not _ark_is_available():
        logger.debug(
            "Skip registering inc_ark_mxfp4_hadamard_quant: ARK is unavailable."
        )
        return False
    if not hasattr(torch.ops.vllm, "inc_ark_mxfp4_hadamard_quant"):
        direct_register_custom_op(
            op_name="inc_ark_mxfp4_hadamard_quant",
            op_func=_inc_ark_mxfp4_hadamard_quant_impl,
            mutates_args=[],
            fake_impl=_inc_ark_mxfp4_hadamard_quant_fake,
            dispatch_key=current_platform.dispatch_key,
        )
    _OPS_REGISTERED = True
    return True


def is_available() -> bool:
    """Return True iff the fused ARK Hadamard+MXFP4 XPU op can be used."""
    return _register_ops_once()


def mxfp4_hadamard_quantize(
    x: torch.Tensor,
) -> tuple[torch.Tensor, torch.Tensor]:
    """Fused Hadamard rotation + MXFP4 quantization via the ARK XPU kernel.

    Returns ``(fp4, scale)`` typed as ``float4_e2m1fn_x2`` / ``float8_e8m0fnu``
    to match :func:`xpu_mxfp4_quantize`. ``x`` must be 2-D and contiguous with a
    last dimension divisible by 32.
    """
    if not _register_ops_once():
        raise RuntimeError(
            "auto_round_kernel (ARK) fused MXFP4 Hadamard op is unavailable."
        )
    q, s = torch.ops.vllm.inc_ark_mxfp4_hadamard_quant(x)
    return q.view(torch.float4_e2m1fn_x2), s.view(torch.float8_e8m0fnu)


# Attempt registration at import time (no-op if ARK is unavailable).
_register_ops_once()
