class NPUMxfp4LinearMethod(MXFPLinearMethodBase):
    """NPU W4A4 MXFP4 offline linear method for pre-quantized checkpoints.

    Weight canonical layout after process_weights_after_loading:
      weight      : (N, K) in float4_e2m1fn_x2  — NOT pre-transposed (FP4 packed)
      weight_scale: (N, S/2, 2) in float8_e8m0fnu — NOT pre-transposed

    Both are transposed inline in _quant_matmul, unlike MXFP8 which pre-transposes.
    NPUMxfp4OnlineLinearMethod normalizes to the same layout so apply() is shared.
    """

    def __init__(self, quant_config: DiffusionMXFP4Config) -> None:
        self.quant_config = quant_config
        self.out_dtype = torch.get_default_dtype()

    params_dtype: torch.dtype,
    **extra_weight_attrs,
) -> None:
    if input_size_per_partition % 32 != 0:
        raise ValueError(
            "MXFP4 requires input_size_per_partition "
            f"({input_size_per_partition}) to be divisible by 32."
        )
    super().create_weights(
        layer,
        input_size_per_partition,
        output_partition_sizes,
        input_size,
        output_size,
        params_dtype,
        **extra_weight_attrs,
    )

def process_weights_after_loading(self, layer: Module) -> None:
    if getattr(layer, "_already_called_process_weights_after_loading", False):
        return

    if layer.weight.device == torch.device("meta"):
        weight = ModelWeightParameter(
            data=torch.empty_like(layer.weight, device=layer._load_device),
            input_dim=1,
            output_dim=0,
            weight_loader=layer.weight.weight_loader,
        )
        _copy_missing_attrs(layer.weight, weight)
        layer.register_parameter("weight", weight)
        initialize_single_dummy_weight(layer.weight)

    # Importing the XPU op module registers vllm.xpu_mxfp4_quantize.
    import vllm._xpu_ops  # noqa: F401
    from vllm.model_executor.layers.quantization.utils.mxfp4_utils import (
        xpu_mxfp4_quantize,
    )

    weight = layer.weight.contiguous()
    if self.hadamard_block_size > 1:
        # Rotate the weight along K (last dim) with the same Hadamard matrix
        # the activation uses, so (x @ H) @ (W @ H).T == x @ W.T.
        from vllm_omni.quantization._hadamard import apply_block_hadamard

        weight = apply_block_hadamard(weight, self.hadamard_block_size).contiguous()

    weight_fp4, weight_scale = xpu_mxfp4_quantize(weight)
    replace_parameter(layer, "weight", weight_fp4.data)
    replace_parameter(layer, "weight_scale", weight_scale.data)
    self.kernel.process_weights_after_loading(layer)
    layer._already_called_process_weights_after_loading = True

