    )

    if self.hadamard_block_size > 1:
        # Rotate the activation along K (last dim) before MXFP4 quantization;
        # the matching weight rotation is applied at load time.
        from vllm_omni.quantization._hadamard import apply_block_hadamard

        x = apply_block_hadamard(x, self.hadamard_block_size)

    return xpu_mxfp4_quantize(x.contiguous())

